/**
 * The context-free readings of one Arabic word (src/adapters/arabic/analyze.ts) over the MINI FIXTURE (test/adapters/arabic-mini-index.json,
 * about 140 real Wiktionary entries with every table row, generated by scripts/ar-mini-index.mts). Every test states what must hold.
 * The sentences and words are the test author's own.
 */
import fs from 'node:fs';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { AnalysisCandidate, RawToken } from '../../src/core';
import { arWordCandidates } from '../../src/adapters/arabic/analyze';
import { describeArMorph } from '../../src/adapters/arabic/describe';
import { installArabicIndex, resetArabicIndexes, type ArabicFormIndex } from '../../src/adapters/arabic/index-store';
import { arKey } from '../../src/adapters/arabic/text';

const fixture = JSON.parse(fs.readFileSync(new URL('./arabic-mini-index.json', import.meta.url), 'utf8')) as ArabicFormIndex;
beforeAll(() => { resetArabicIndexes(); installArabicIndex(fixture); });
afterAll(() => resetArabicIndexes());

const token = (surface: string): RawToken => ({ surface, start: 0, end: surface.length, isWord: true, normalized: arKey(surface) });
const cands = (surface: string): AnalysisCandidate[] => arWordCandidates(token(surface));
const top = (surface: string): AnalysisCandidate => cands(surface)[0];
const lemmas = (cs: AnalysisCandidate[]): string[] => [...new Set(cs.map((c) => c.lemma ?? '?'))];
const partTexts = (c: AnalysisCandidate): string[] => (c.parts ?? []).map((p) => p.text);

describe('verbs (fully vocalized: the page decides, one lexeme, 0.90)', () => {
  it('كَتَبَ: lemma كَتَبَ, perfect 3rd masculine singular active; the other lexemes of the key (كَتَّبَ, كُتِبَ) are gone', () => {
    const cs = cands('كَتَبَ');
    expect(lemmas(cs)).toEqual(['كَتَبَ']);
    expect(cs[0]).toMatchObject({ pos: 'VERB', confidence: 0.9, morph: { Aspect: 'Perf', Person: '3', Gender: 'Masc', Number: 'Sing', Voice: 'Act', Form: 'I' } });
    expect(cs[0].notes).toMatchObject({ root: 'ك ت ب', rootClass: 'sound', vowels: 'source' });
    expect(cs[0].varieties).toEqual(['ar-msa', 'ar-cla']);
    expect(describeArMorph(cs[0].morph, 'VERB')).toBe('perfect (completed action), 3rd person masculine singular, active, form I');
  });
  it('كَتَبْتُ is 1st person; كَتَبْنَا is 1st person plural', () => {
    expect(top('كَتَبْتُ')).toMatchObject({ lemma: 'كَتَبَ', confidence: 0.9, morph: { Person: '1', Number: 'Sing' } });
    expect(top('كَتَبْنَا')).toMatchObject({ lemma: 'كَتَبَ', morph: { Person: '1', Number: 'Plur' } });
  });
  it('تَكْتُبُ: ONE candidate for "you (m. sg.)" and "she": Person=2,3, and the description says so', () => {
    const cs = cands('تَكْتُبُ').filter((c) => c.lemma === 'كَتَبَ');
    expect(cs).toHaveLength(1);
    expect(cs[0].morph).toMatchObject({ Person: '2,3', Mood: 'Ind', Aspect: 'Imp', Number: 'Sing' });
    expect(cs[0].confidence).toBe(0.9);
    expect(describeArMorph(cs[0].morph, 'VERB')).toContain('you (m. sg.) or she');
  });
  it('يَكْتُبُونَ: imperfect indicative 3rd masculine plural; كُتِبَ: passive of كَتَبَ', () => {
    expect(top('يَكْتُبُونَ')).toMatchObject({ lemma: 'كَتَبَ', confidence: 0.9, morph: { Aspect: 'Imp', Mood: 'Ind', Person: '3', Number: 'Plur', Gender: 'Masc' } });
    expect(top('كُتِبَ')).toMatchObject({ lemma: 'كَتَبَ', morph: { Voice: 'Pass', Aspect: 'Perf' } });
  });
  it('قَالَ is ONE lexeme although two entries share its head (to say / to nap): one candidate, glosses numbered, notes.homonyms = 2', () => {
    const cs = cands('قَالَ');
    expect(cs).toHaveLength(1);
    expect(cs[0]).toMatchObject({ lemma: 'قَالَ', confidence: 0.9 });
    expect(cs[0].notes?.homonyms).toBe('2');
    expect(cs[0].gloss).toMatch(/^1\. .*2\. /);
  });
  it('قُلْ is the imperative of قَالَ (hollow root); يَعِدُ is of وَعَدَ (assimilated); اِرْمِ is of رَمَى (defective)', () => {
    expect(top('قُلْ')).toMatchObject({ lemma: 'قَالَ', morph: { Mood: 'Imp', Person: '2' } });
    expect(top('يَعِدُ')).toMatchObject({ lemma: 'وَعَدَ', morph: { Aspect: 'Imp', Mood: 'Ind' } });
    expect(top('يَعِدُ').notes?.rootClass).toBe('assimilated');
    expect(top('اِرْمِ')).toMatchObject({ lemma: 'رَمَى', morph: { Mood: 'Imp' } });
    expect(top('اِرْمِ').notes?.rootClass).toBe('defective');
  });
  it('derived forms: اِسْتَغْفَرَ is form X, تَعَلَّمَ form V, each its own lemma', () => {
    expect(top('اِسْتَغْفَرَ')).toMatchObject({ lemma: 'اِسْتَغْفَرَ', morph: { Form: 'X', Aspect: 'Perf' } });
    expect(top('تَعَلَّمَ')).toMatchObject({ lemma: 'تَعَلَّمَ', morph: { Form: 'V' } });
    expect(lemmas(cands('تَعَلَّمَ'))).toEqual(['تَعَلَّمَ']);
  });
  it('J3: a fully vocalized page prints its shaddas: كَتَبْتُ is not كَتَّبْتُ (form II), and مَدَّ is not مَدَ', () => {
    expect(lemmas(cands('كَتَبْتُ'))).toEqual(['كَتَبَ']);
    expect(top('مَدَّ')).toMatchObject({ lemma: 'مَدَّ', pos: 'VERB' });
    expect(lemmas(cands('مَدَ'))).not.toContain('مَدَّ');
  });
  it('رَآهُ is رَأَى + ه (the madda is the hamza seat before the pronoun); the verb is the one lexeme at or above 0.5', () => {
    const cs = cands('رَآهُ');
    expect(cs[0]).toMatchObject({ lemma: 'رَأَى', pos: 'VERB', morph: { Person: '3', Number: 'Sing' } });
    expect(cs[0].confidence).toBeGreaterThanOrEqual(0.5);
    expect(cs.filter((c) => c.confidence >= 0.5).every((c) => c.lemma === 'رَأَى')).toBe(true);
    expect(partTexts(cs[0])).toEqual(['رَآ', 'هُ']);
  });
  it('رَأَيْتُمُوهُمْ: ـتمو before a pronoun is read: رَأَى, 2nd person plural, with the object هُمْ', () => {
    const c = top('رَأَيْتُمُوهُمْ');
    expect(c).toMatchObject({ lemma: 'رَأَى', morph: { Person: '2', Number: 'Plur', Aspect: 'Perf' } });
    expect(c.parts?.[c.parts.length - 1].morph).toMatchObject({ Person: '3', Number: 'Plur' });
  });
});

describe('nouns, plurals, duals, the article and attached pronouns', () => {
  it('كُتُب: the broken plural of كِتَاب (lemma كِتَاب, Number=Plur, PluralType=Broken)', () => {
    expect(top('كُتُب')).toMatchObject({ lemma: 'كِتَاب', pos: 'NOUN', morph: { Number: 'Plur', PluralType: 'Broken' } });
  });
  it('مُعَلِّمُونَ is the sound masculine plural of مُعَلِّم, nominative; the case comes from the printed ending', () => {
    expect(top('مُعَلِّمُونَ')).toMatchObject({ lemma: 'مُعَلِّم', morph: { Number: 'Plur', Case: 'Nom', PluralType: 'Sound' } });
  });
  it('J6: the definite sound plural keeps its case: المُعَلِّمُونَ is Nom, والمعلمين is Acc,Gen with the article read as a clitic', () => {
    expect(top('الْمُعَلِّمُونَ').morph).toMatchObject({ Definite: 'Def', Case: 'Nom', Number: 'Plur' });
    const c = top('والمعلمين');
    expect(c.lemma).toBe('مُعَلِّم');
    expect(c.morph).toMatchObject({ Definite: 'Def', Case: 'Acc,Gen' });
    expect(partTexts(c)).toEqual(['و', 'ال', 'معلمين']);
  });
  it('مُعَلِّمَات: the sound feminine plural; both مُعَلِّم and مُعَلِّمَة hold it, so neither is credited (≤ 0.45)', () => {
    const cs = cands('مُعَلِّمَات');
    expect(lemmas(cs).sort()).toEqual(['مُعَلِّم', 'مُعَلِّمَة'].sort());
    expect(Math.max(...cs.map((c) => c.confidence))).toBeLessThanOrEqual(0.45);
  });
  it('كِتَابَانِ is the dual nominative, كِتَابَيْنِ the dual accusative or genitive', () => {
    expect(top('كِتَابَانِ')).toMatchObject({ lemma: 'كِتَاب', morph: { Number: 'Dual', Case: 'Nom' } });
    expect(cands('كِتَابَيْنِ').find((c) => c.morph.Pausal !== 'Yes')?.morph).toMatchObject({ Number: 'Dual', Case: 'Acc,Gen' });
  });
  it('كِتَابُهُ: كِتَاب + a possessive pronoun, construct state, nominative; parts are slices of the printed word', () => {
    const c = top('كِتَابُهُ');
    expect(c).toMatchObject({ lemma: 'كِتَاب', confidence: 0.85, morph: { Definite: 'Cons', Case: 'Nom' } });
    expect(partTexts(c)).toEqual(['كِتَابُ', 'هُ']);
    expect(c.parts?.[0].kind).toBe('stem');
    expect(c.parts?.[1]).toMatchObject({ kind: 'suffix', morph: { Person: '3', Number: 'Sing', Gender: 'Masc' } });
    expect(c.notes?.segmentation).toContain('كتاب');
  });
  it('بِالْكِتَابِ: ب + ال + كتاب, genitive definite; its case is the page\'s, not an inference', () => {
    const c = top('بِالْكِتَابِ');
    expect(c).toMatchObject({ lemma: 'كِتَاب', morph: { Definite: 'Def', Case: 'Gen' } });
    expect(partTexts(c)).toEqual(['بِ', 'الْ', 'كِتَابِ']);
    expect(c.parts?.[0]).toMatchObject({ kind: 'prefix', pos: 'ADP' });
    expect(c.parts?.[1]).toMatchObject({ kind: 'prefix', pos: 'DET' });
    expect(c.notes?.caseSource).toBeUndefined();
  });
  it('لِلْبَيْتِ: ل + ال + بيت with ONE lām printed twice (لل), and the parts cover the word', () => {
    const c = top('لِلْبَيْتِ');
    expect(c).toMatchObject({ lemma: 'بَيْت', morph: { Definite: 'Def', Case: 'Gen' } });
    expect(partTexts(c)).toEqual(['لِ', 'لْ', 'بَيْتِ']);
    expect(partTexts(c).join('')).toBe('لِلْبَيْتِ');
  });
  it('الشَّمْس and الْقَمَر: the article is a prefix and the sun letter\'s shadda is not a conflict', () => {
    expect(top('الشَّمْس')).toMatchObject({ lemma: 'شَمْس', morph: { Definite: 'Def', Gender: 'Fem' } });
    expect(partTexts(top('الشَّمْس'))).toEqual(['ال', 'شَّمْس']);
    expect(top('الْقَمَر')).toMatchObject({ lemma: 'قَمَر', morph: { Definite: 'Def' } });
  });
  it('the case a preposition implies, when the page printed no ending, is noted as inferred and is never a feature value it did not show', () => {
    const c = top('بالكتاب');
    expect(c.lemma).toBe('كِتَاب');
    expect(c.morph.Definite).toBe('Def');
    if (c.notes?.case) expect(c.notes.caseSource).toBe('inferred');
  });
});

describe('unvocalized words: never credit the wrong lexeme', () => {
  it('كتب: several lexemes (a verb, another verb, a plural noun, a verbal noun), none above 0.45, all kept, كَتَبَ and كِتَاب among them', () => {
    const cs = cands('كتب');
    const ls = lemmas(cs);
    expect(ls).toEqual(expect.arrayContaining(['كَتَبَ', 'كَتَّبَ', 'كِتَاب']));
    expect(Math.max(...cs.map((c) => c.confidence))).toBeLessThanOrEqual(0.45);
    expect(cs.every((c) => c.notes?.identity === 'undecided')).toBe(true);
    expect(cs.length).toBeLessThanOrEqual(12);
  });
  it('J1: a verbal noun with no entry of its own is ONE lemma, its bare head (no case ending), notes.derivedFrom the verb', () => {
    const d = cands('كتب').find((c) => c.notes?.derivation === 'verbal noun');
    expect(d).toMatchObject({ lemma: 'كَتْب', pos: 'NOUN' });
    expect(d?.notes?.derivedFrom).toBe('كَتَبَ');
    for (const c of cands('كتب').filter((x) => x.notes?.derivation)) expect(c.lemma).not.toMatch(/[ً-ِ]$/);
  });
  it('J2: a participle that has an entry of its own is not also emitted as derived from the verb: كَاتِب appears as NOUN and ADJ entries only', () => {
    const cs = cands('كَاتِب');
    expect(cs.some((c) => c.notes?.derivedFrom)).toBe(false);
    expect(cs.filter((c) => c.pos !== 'VERB').map((c) => c.pos).sort()).toEqual(['ADJ', 'NOUN']);
  });
  it('the order is confidence, then plainness; a whole-word reading of a real lemma comes before a cut onto a derived cell', () => {
    const cs = cands('كتب');
    const iVerb = cs.findIndex((c) => c.lemma === 'كَتَبَ');
    const iCut = cs.findIndex((c) => c.parts && c.notes?.derivation);
    if (iCut >= 0) expect(iVerb).toBeLessThan(iCut);
    for (let i = 1; i < cs.length; i++) expect(cs[i - 1].confidence).toBeGreaterThanOrEqual(cs[i].confidence);
  });
  it('the Korean rule: in an undecided set no reading reaches 0.5; in a decided word exactly one lexeme is at or above 0.5', () => {
    for (const w of ['كتب', 'علم', 'وجد', 'ولد']) {
      const cs = cands(w);
      const decided = cs.some((c) => c.notes?.identity === 'structural' || c.notes?.identity === 'main');
      const high = new Set(cs.filter((c) => c.confidence >= 0.5).map((c) => c.lemma));
      if (decided) expect(high.size, w).toBe(1); else expect(high.size, w).toBe(0);
    }
  });
  it('علم: عِلْم, عَلَم, عَلِمَ, عَلَّمَ stay four lexemes (homographs are distinct)', () => {
    expect(lemmas(cands('علم'))).toEqual(expect.arrayContaining(['عِلْم', 'عَلَم', 'عَلِمَ', 'عَلَّمَ']));
  });
  it('وَجَدَ: the whole-word verb comes first; و + جد is below it. Three entries share the head and are ONE lexeme', () => {
    const cs = cands('وَجَدَ');
    expect(cs).toHaveLength(1);
    expect(cs[0].notes?.homonyms).toBe('3');
    const bare = cands('وجد');
    expect(bare[0]).toMatchObject({ lemma: 'وَجَدَ', pos: 'VERB' });
    expect(bare[0].parts).toBeUndefined();
    const cut = bare.find((c) => c.parts?.[0]?.text === 'و');
    if (cut) expect(bare.indexOf(cut)).toBeGreaterThan(0);
    expect(bare[0].confidence).toBeGreaterThanOrEqual(bare.find((c) => c !== bare[0])?.confidence ?? 0);
  });
  it('ولد: the verb and the noun are whole-word readings first; و + لد (the imperative of the verb) is only a cut below them', () => {
    const cs = cands('ولد');
    expect(cs[0].parts).toBeUndefined();
    expect(cs.findIndex((c) => c.parts?.[0]?.text === 'و')).not.toBe(0);
    expect(lemmas(cs)).toEqual(expect.arrayContaining(['وَلَدَ', 'وَلَد']));
  });
  it('بيت is never cut as ب + يت (يت is no word), and كل is never ك + ل', () => {
    expect(cands('بيت').some((c) => c.parts)).toBe(false);
    expect(cands('بيت')[0]).toMatchObject({ lemma: 'بَيْت', confidence: 0.9 });
    expect(cands('كل').some((c) => c.parts?.[0]?.text === 'ك')).toBe(false);
    expect(cands('كل')[0].lemma).toBe('كُلّ');
  });
  it('a reading that needs a cut where a whole word is a lemma\'s own citation form is marginal: كل is كُلّ (structural, 0.60), not the imperative كُلْ', () => {
    const cs = cands('كل');
    expect(cs[0]).toMatchObject({ lemma: 'كُلّ', confidence: 0.6 });
    expect(cs[0].notes?.identity).toBe('structural');
    expect(cs.find((c) => c.lemma === 'أَكَلَ')!.confidence).toBeLessThanOrEqual(0.45);
  });
  it('the vowels the page prints select among lexemes: كُتِبَ leaves one (0.90)', () => {
    expect(cands('كُتِبَ').filter((c) => c.confidence >= 0.5)).toHaveLength(1);
    expect(cands('كُتُب')[0]).toMatchObject({ lemma: 'كِتَاب', confidence: 0.9 });
  });
  it('printed vowels decide before the structural layer: a partly vocalized word with one agreeing lexeme is credited (0.75)', () => {
    const c = top('كُتُب');
    expect(c.confidence).toBeGreaterThanOrEqual(0.75);
  });
});

describe('closed-class words, hand priors and clitic chains', () => {
  it('من: مِنْ "from" is the main reading (hand prior 0.70) and مَنْ "who" stays listed below it', () => {
    const cs = cands('من');
    expect(cs[0]).toMatchObject({ lemma: 'مِنْ', pos: 'ADP', confidence: 0.7 });
    expect(cs[0].notes?.identity).toBe('main');
    expect(lemmas(cs)).toContain('مَنْ');
    expect(cs.find((c) => c.lemma === 'مَنْ')!.confidence).toBeLessThanOrEqual(0.45);
  });
  it('closed-class words the tables lack come from the hand table: لَنْ governs the subjunctive; origin hand', () => {
    const c = cands('لن').find((x) => x.lemma === 'لَنْ');
    expect(c).toBeDefined();
    expect(c!.notes?.governs).toBe('subjunctive');
  });
  it('عليه is one word of the closed table or the index with its pronoun, never twice: عَلَى + 3rd masculine singular', () => {
    const cs = cands('عليه').filter((c) => c.lemma === 'عَلَى');
    expect(cs.length).toBeGreaterThan(0);
    expect(new Set(cs.map((c) => JSON.stringify(c.morph))).size).toBe(cs.length);
    expect(cs[0].morph).toMatchObject({ Person: '3', Number: 'Sing', Gender: 'Masc' });
  });
  it('لَهُ: ل + ه as the closed table lists it (lemma لِ, Person 3), with its two parts', () => {
    const c = top('لَهُ');
    expect(c).toMatchObject({ lemma: 'لِ', pos: 'ADP', morph: { Person: '3', Number: 'Sing', Gender: 'Masc' } });
    expect(partTexts(c)).toEqual(['لَ', 'هُ']);
  });
  it('فسيكتبونها: ف + س + يكتبون + ها, lemma كَتَبَ first; the future prefix fixes the mood to the indicative', () => {
    const c = top('فسيكتبونها');
    expect(c).toMatchObject({ lemma: 'كَتَبَ', pos: 'VERB', morph: { Aspect: 'Imp', Mood: 'Ind', Person: '3', Number: 'Plur', Gender: 'Masc' } });
    expect(partTexts(c)).toEqual(['ف', 'س', 'يكتبون', 'ها']);
    expect(c.parts?.map((p) => p.kind)).toEqual(['prefix', 'prefix', 'stem', 'suffix']);
  });
  it('وبالكتاب: four parts و + ب + ال + كتاب on every reading; the lexemes كِتَاب and كُتَّاب (the plural of كَاتِب) share the key, so neither is credited', () => {
    const cs = cands('وبالكتاب');
    expect(cs.length).toBeGreaterThan(0);
    for (const c of cs) expect(partTexts(c)).toEqual(['و', 'ب', 'ال', 'كتاب']);
    expect(lemmas(cs)).toContain('كِتَاب');
    expect(cs.every((c) => c.confidence <= 0.45)).toBe(true);
  });
  it('وهم: the function-word chain و + هُمْ is a reading (the lead\'s reviewed identity, when listed, may promote it)', () => {
    const c = cands('وهم').find((x) => x.parts?.[0]?.text === 'و');
    expect(c).toMatchObject({ lemma: 'هُمْ', pos: 'PRON' });
  });
  it('مدرسته (ة → ت), معلموه (ون → و), كتبوه (وا → و), رماه (ى → ا): the stem is read in its dictionary spelling', () => {
    expect(top('مدرسته')).toMatchObject({ lemma: 'مَدْرَسَة', morph: { Definite: 'Cons' } });
    expect(partTexts(top('مدرسته'))).toEqual(['مدرست', 'ه']);
    expect(top('معلموه')).toMatchObject({ lemma: 'مُعَلِّم', morph: { Number: 'Plur', Case: 'Nom' } });
    expect(cands('كتبوه').find((c) => c.lemma === 'كَتَبَ')?.morph).toMatchObject({ Person: '3', Number: 'Plur', Aspect: 'Perf' });
    expect(top('رماه')).toMatchObject({ lemma: 'رَمَى', morph: { Person: '3', Number: 'Sing' } });
  });
  it('للكتاب: ل + ال + كتاب, parts ل, ل, كتاب', () => {
    const c = cands('للكتاب').find((x) => x.lemma === 'كِتَاب')!;
    expect(partTexts(c)).toEqual(['ل', 'ل', 'كتاب']);
  });
});

describe('spelling: loose forms, Farsi yeh, typing habits', () => {
  it('اكل (no hamza): أَكَلَ is reached by the loose fold, says so (notes.spelling = restored) and is lowered by 0.10', () => {
    const c = cands('اكل').find((x) => x.lemma === 'أَكَلَ');
    expect(c).toBeDefined();
    expect(c!.notes?.spelling).toBe('restored');
    expect(c!.confidence).toBeLessThanOrEqual(0.8);
  });
  it('J4: a loose-fold reading never beats a direct one: أكل as written has no restored reading at the top', () => {
    expect(top('أَكَلَ').notes?.spelling).toBeUndefined();
    const cs = cands('اكل');
    const direct = cs.filter((c) => c.notes?.spelling !== 'restored');
    if (direct.length) expect(cs[0].notes?.spelling).not.toBe('restored');
  });
  it('J4: on a page that prints vowels a bare initial alif is hamzat al-waṣl: اِسْتَغْفَرَ is not read as a hamza word', () => {
    expect(top('اِسْتَغْفَرَ').notes?.spelling).toBeUndefined();
  });
  it('a Farsi yeh: علی is read under BOTH keys (على and علي), as direct readings', () => {
    const ls = lemmas(cands('علی'));
    expect(ls).toEqual(expect.arrayContaining(['عَلَى', 'عَلِيّ']));
    expect(cands('علی').every((c) => c.notes?.spelling !== 'restored')).toBe(true);
  });
  it('J7: قارىء (ىء typed for ئ) is read through the typing variant, marked restored, without parts', () => {
    const c = top('قارىء');
    expect(c).toBeDefined();
    expect(c.notes?.spelling).toBe('restored');
    expect(c.parts).toBeUndefined();
  });
});

describe('guesses, rare words and non-words', () => {
  it('a word no source has: a sound feminine plural is a marked guess (≤ 0.35, unconfirmed, no gloss, no lemma); anything else gets nothing', () => {
    const g = cands('سيارات');
    expect(g).toHaveLength(1);
    expect(g[0]).toMatchObject({ pos: 'NOUN', unconfirmed: true });
    expect(g[0].confidence).toBeLessThanOrEqual(0.35);
    expect(g[0].gloss).toBeUndefined();
    expect(g[0].lemma).toBeUndefined();
    expect(cands('ضضضض')).toEqual([]);
  });
  it('J7: an unknown nisba (feminine -ية) of a known noun is a guess, marked unconfirmed, notes.nisbaOf the noun', () => {
    const g = cands('مدرسية');
    expect(g).toHaveLength(1);
    expect(g[0]).toMatchObject({ pos: 'ADJ', unconfirmed: true });
    expect(g[0].notes?.nisbaOf).toBe('مَدْرَسَة');
  });
  it('a token that is not a word, or has no Arabic letter, gives nothing', () => {
    expect(arWordCandidates({ ...token('٣٤'), isWord: false })).toEqual([]);
    expect(cands('abc')).toEqual([]);
  });
});

describe('J8: a rare lexeme on a very short key is not read confidently', () => {
  const tiny: ArabicFormIndex = {
    schema: 1, id: 'ar-test-rare', built: '2026-11-25', codes: [''], lemmaIds: ['ذحم|NOUN'], lemmas: { 'ذحم|NOUN': ['ذَحْم', '', 'NOUN', '', 0] },
    forms: { ذحم: [[0, 0]] }, loose: {}, source: { label: 'test', licence: 'n/a', url: '' },
  };
  it('a count-0 lemma on a 3-letter key gets at most 0.45 and notes.identity = rare, unless the page prints vowels', () => {
    installArabicIndex(tiny);
    const c = cands('ذحم')[0];
    expect(c.confidence).toBeLessThanOrEqual(0.45);
    expect(c.notes?.identity).toBe('rare');
    expect(cands('ذَحْم')[0].confidence).toBeGreaterThan(0.45);
  });
});
